const CHAT_ID = "6338575677"; // <-- el mismo chat id
const chatId = String(msg.payload.chatId);
if (chatId !== CHAT_ID) return null; // ignora a desconocidos

const text = String(msg.payload.content || "").trim().toLowerCase().replace(/@\w+$/, "");
if (text !== "/stats" && text !== "stats") return null;

msg.mode = "stats";
msg.chatId = chatId;
return msg;

msg.url = "https://www.iberdrola.es/o/webclipb/iberdrola/puntosrecargacontroller/getListarPuntosRecarga";
msg.method = "POST";
msg.headers = {
  "Content-Type": "application/json",
  "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
  "Accept": "application/json, text/plain, */*",
  "Accept-Language": "es-ES,es;q=0.9",
  "Origin": "https://www.iberdrola.es",
  "Referer": "https://www.iberdrola.es/clientes/puntos-recarga"
};
msg.payload = {
  dto: {
    chargePointTypesCodes: ["P", "R", "I", "N"],
    socketStatus: [],
    advantageous: false,
    connectorsType: [],
    loadSpeed: [],
    latitudeMax: 39.59354704714217,
    latitudeMin: 39.58362536023294,
    longitudeMax: -0.33177372823335327,
    longitudeMin: -0.34602162252046265
  },
  language: "es"
};
return msg;

const CHAT_ID = "6338575677"; // <-- tu chat id de Telegram
const CHARGERS = {
  95684:  { alias: "BIBLIOTECA", emoji: "📚" },
  161375: { alias: "AJUNTAMENT", emoji: "🏛️" },
  147587: { alias: "CASA",       emoji: "🏠" },
  147607: { alias: "CASA IAIA",  emoji: "👵" }
};

const MAX_FALLOS = 20; // ~5 min con consultas cada 15 s
const send = (chatId, text) => ({ payload: { chatId, type: "message", content: text } });
const label = (st) => st === "AVAILABLE" ? "🟢 LIBRE" : st === "OCCUPIED" ? "🔴 OCUPADO" : "⚪ " + st;

let data = null;
if (typeof msg.payload === "string") {
  try { data = JSON.parse(msg.payload); }
  catch (e) {
    node.warn(`Respuesta no JSON (HTTP ${msg.statusCode}): ` + msg.payload.slice(0, 300).replace(/\s+/g, " "));
  }
}
const ok = msg.statusCode === 200 && data && Array.isArray(data.entidad);
let fallos = flow.get("fallos") || 0;

if (!ok) {
  node.status({ fill: "red", shape: "ring", text: "error API " + msg.statusCode });
  if (msg.mode === "stats") {
    return [send(msg.chatId, "⚠️ No he podido consultar la web de Iberdrola ahora mismo.")];
  }
  fallos++;
  flow.set("fallos", fallos);
  if (fallos === MAX_FALLOS) {
    return [send(CHAT_ID, "⚠️ Llevo varios minutos sin poder consultar Iberdrola. Puede que hayan bloqueado la IP o la web esté caída. (Último código HTTP: " + msg.statusCode + ")")];
  }
  return null;
}

// Estado actual de nuestros cargadores
const actual = {};
for (const cp of data.entidad) {
  const info = CHARGERS[cp.cpId];
  if (!info) continue;
  let st = cp.cpStatus?.statusCode || "UNKNOWN";
  if (st === "RESERVED") st = "OCCUPIED";
  actual[cp.cpId] = st;
}
node.status({ fill: "green", shape: "dot", text: new Date().toLocaleTimeString("es-ES") });

// Comando /stats
if (msg.mode === "stats") {
  let t = "📊 Estado de los cargadores\n\n";
  for (const [id, info] of Object.entries(CHARGERS)) {
    t += `${info.emoji} ${info.alias}: ${label(actual[id] || "DESCONOCIDO")}\n`;
  }
  return [send(msg.chatId, t)];
}

// Monitorización: avisar solo al pasar de no-libre a libre
const out = [];
if (fallos >= MAX_FALLOS) out.push(send(CHAT_ID, "✅ Conexión con Iberdrola recuperada."));
flow.set("fallos", 0);

const prev = flow.get("estados") || {};
for (const [id, st] of Object.entries(actual)) {
  const before = prev[id];
  if (before !== undefined && before !== "AVAILABLE" && st === "AVAILABLE") {
    const info = CHARGERS[id];
    out.push(send(CHAT_ID, `🔋 ¡Cargador disponible!\n\n${info.emoji} ${info.alias}\n\n🟢 Estado: LIBRE`));
  }
}
flow.set("estados", { ...prev, ...actual });
return out.length ? [out] : null;
